<template>
  <div class="card mb-3">
    <div class="row no-gutters">
      <div class="col-md-4">
        <!-- <img
          :src="user.image | emptyImage"
          width="300px"
          height="300px"
        > -->
        <img :src="user.image | emptyUserImage"
        style="width: 300px;">
        <!-- <img :src="`https://picsum.photos/300/300?random=${Math.floor(Math.random() * 1000)}`"
        style="width: 300px;"> -->
      </div>
      <div class="col-md-8">
        <div class="card-body">
          <h5 class="card-title">
            {{ user.name }}
          </h5>
          <p class="card-text">
            {{ user.email }}
          </p>
          <ul class="list-unstyled">
            <li>
              <strong>{{ user.commentsLength }}</strong> 已評論餐廳
            </li>
            <li>
              <strong>{{ user.favoritedRestaurantsLength }}</strong> 收藏的餐廳
            </li>
            <li>
              <strong>{{ user.followingsLength }}</strong> followings (追蹤者)
            </li>
            <li>
              <strong>{{ user.followersLength }}</strong> followers (追隨者)
            </li>
          </ul>
          <template v-if="isCurrentUser">
            <router-link :to="{ name: 'user-edit', params: { id: user.id } }" class="btn btn-primary">
              Edit
            </router-link>
          </template>
          <template v-else>
            <button v-if="isFollowed" type="button" class="btn btn-danger"
              @click.stop.prevent="deleteFollowing(user.id)">
              取消追蹤
            </button>
            <button v-else type="button" class="btn btn-primary" @click.stop.prevent="addFollowing(user.id)">
              追蹤
            </button>
          </template>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import usersAPI from '@/apis/users'
import { Toast } from '@/utils/helpers';
// import { mapState } from 'vuex';
import { emptyUserImageFilter } from '@/utils/mixins';

export default {
  mixins: [emptyUserImageFilter],
  props: {
    user: {
      type: Object,
      default: () => ({})
    },
    initialIsFollowed: {
      type: Boolean,
      required: true,
    },
    currentUser: {
      type: Object,
      default: () => ({})
    }
  },
  data() {
    return {
      isFollowed: this.initialIsFollowed
    }
  },
  computed: {
    isCurrentUser() {
      return this.user.id === this.currentUser.id
    }
  },
  watch: {
    initialIsFollowed(newVal) {
      this.isFollowed = newVal
    }
  },
  methods: {
    // async ad
    async addFollowing(userId) {
      try {
        const { data } = await usersAPI.addFollowing(userId)
        if (data.status !== 'success') {
          throw new Error(data.message)
        }

        // this.followers.push(this.currentUser)
        // this.user.followersLength++
        this.isFollowed = true
      } catch (error) {
        console.log('error', error)

        Toast.fire({
          icon: 'error',
          title: '無法追蹤，請稍候再試'
        })
      }
    },
    async deleteFollowing(userId) {
      try {
        const { data } = await usersAPI.deleteFollowing(userId)
        if (data.status !== 'success') {
          throw new Error(data.message)
        }

        // this.followers = this.followers.filter(user => user.id !== this.currentUser.id)
        // this.user.followersLength--
        this.isFollowed = false
      } catch (error) {
        console.log('error', error)

        Toast.fire({
          icon: 'error',
          title: '無法取消追蹤，請稍候再試'
        })
      }
    },
  }
}
</script>